import os, re, sys, glob

root = sys.argv[1]
files = ["README.md"] + sorted(glob.glob(os.path.join(root, "docs/*.md"))) + sorted(glob.glob(os.path.join(root, "docs/adr/*.md"))) + sorted(glob.glob(os.path.join(root, "diagrams/*.md"))) + ["examples/README.md"]
files = [f if os.path.isabs(f) else os.path.join(root, f) for f in files]

def slug(h):
    h = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", h)  # link text
    h = h.strip().lower()
    h = re.sub(r"[^\w\- ]", "", h)  # keep word chars, hyphen, space
    return h.replace(" ", "-")

def anchors(path):
    out = {}
    infence = False
    for line in open(path, encoding="utf-8"):
        if line.lstrip().startswith("```"):
            infence = not infence
            continue
        if infence:
            continue
        m = re.match(r"^(#{1,6})\s+(.*?)\s*#*\s*$", line)
        if m:
            s = slug(m.group(2))
            n = out.get(s, 0)
            out[s] = n + 1
    res = set()
    for s, n in out.items():
        res.add(s)
        for i in range(1, n):
            res.add(f"{s}-{i}")
    return res

bad = 0
for f in files:
    text = open(f, encoding="utf-8").read()
    text_nf = re.sub(r"```.*?```", "", text, flags=re.S)
    for ln, line in enumerate(text_nf.splitlines(), 1):
        pass
    lines = open(f, encoding="utf-8").read().splitlines()
    infence = False
    for ln, line in enumerate(lines, 1):
        if line.lstrip().startswith("```"):
            infence = not infence
            continue
        if infence:
            continue
        line2 = re.sub(r"`[^`]*`", lambda m: m.group(0) if m.group(0).startswith("`[") else "", line)
        for m in re.finditer(r"\]\(([^)\s]+)\)", line):
            tgt = m.group(1)
            if re.match(r"^(https?|mailto):", tgt):
                continue
            path, _, frag = tgt.partition("#")
            if path:
                full = os.path.normpath(os.path.join(os.path.dirname(f), path))
            else:
                full = f
            if not os.path.exists(full):
                print(f"MISSING {os.path.relpath(f, root)}:{ln} -> {tgt}")
                bad += 1
                continue
            if frag:
                if os.path.isdir(full) or not full.endswith(".md"):
                    print(f"ANCHOR-ON-NONMD {os.path.relpath(f, root)}:{ln} -> {tgt}")
                    bad += 1
                    continue
                if frag not in anchors(full):
                    print(f"BAD-ANCHOR {os.path.relpath(f, root)}:{ln} -> {tgt}")
                    bad += 1
print("files checked:", len(files), "broken:", bad)

